-- Stores the frozen A12Q_C2 GPT Native packet in unit_metadata and hands it to GPT Native as an operational event
-- (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C2 stays PENDING.
-- The event carries a pointer to the packet, its hashes and the instructions text; it declares no acceptance.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested).
BEGIN;
DO $a12q_c2_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A12Q';
 v_cp constant text := 'A12Q_C2';
 v_wi constant bigint := 1122;
 v_exec constant text := 'ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A12Q_C2';
 v_packet_sha constant text := '250f2e050ccf0df31c5fc7efe47460fb7e28ef05122f23a531d087676b326a99';
 v_packet jsonb := $pkt${"checkpoint":"C2","deterministic_checks":{"base_keys":["case_id","domains","evidence_refs","reinterpretation_required","verdict"],"cand_keys":["case_id","evidence_refs","fronts","reinterpretation_required","verdict"],"cmp_keys":["baseline_fixed_domains_per_case","baseline_total_domains","candidate_total_fronts","cases_compared"],"request_ref_equals":"REQ-LF-A1Q-C2-PILOT-0001","verdicts":["BLOCKED","REQUIRES_DECISION","NEED_MORE_EVIDENCE"]},"evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"arms\": {\n    \"baseline\": \"Método de dominios fijos: aplica a cada caso la lista completa de dominios obligatorios, independientemente de la evidencia del caso (salida histórica tipo STORY_PACK).\",\n    \"candidate\": \"Método de frentes activados por evidencia: solo registra los frentes materiales que una referencia del propio caso permita justificar (salida tipo paquete de análisis).\"\n  },\n  \"baseline_fixed_domains\": [\n    \"ALCANCE\",\n    \"DATOS\",\n    \"PERMISOS\",\n    \"ESTADOS\",\n    \"ERRORES\",\n    \"EFECTOS_COLATERALES\"\n  ],\n  \"cases\": [\n    {\n      \"case_id\": \"A10-HIST-001\",\n      \"change_family\": \"FEATURE\",\n      \"historical_subject\": \"PROGRAMMING_AGENT_TARGET_STATE_DESIGN_BINDING_REFINEMENT_V1\",\n      \"source_refs\": [\n        \"lf_eventos://20397\",\n        \"github://cristhianlujan/claude-persona-lf-patch/pull/1800\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-002\",\n      \"change_family\": \"MIGRATION\",\n      \"historical_subject\": \"PASE-ATOM-F09-S02\",\n      \"source_refs\": [\n        \"lf_eventos://20356\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-003\",\n      \"change_family\": \"RUNTIME\",\n      \"historical_subject\": \"PASE-ATOM-F09-S03\",\n      \"source_refs\": [\n        \"lf_eventos://20357\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-004\",\n      \"change_family\": \"CONCURRENCY_IDEMPOTENCY\",\n      \"historical_subject\": \"PAULO-148\",\n      \"source_refs\": [\n        \"lf_eventos://20268\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-005\",\n      \"change_family\": \"MODEL_OR_INTELLIGENCE\",\n      \"historical_subject\": \"PROGRAMMING_AGENT_WAVE2_SELECTION_METHOD_CANDIDATE_FREEZE_R2\",\n      \"source_refs\": [\n        \"lf_eventos://20373\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-006\",\n      \"change_family\": \"BUG\",\n      \"historical_subject\": \"INPUT_GOVERNANCE_NUMERIC_SCREEN_IDENTITY\",\n      \"source_refs\": [\n        \"supabase://programacion.fn_input_v58_assertion_template\",\n        \"supabase://programacion.fn_input_v512_assertion_template\",\n        \"supabase://programacion.fn_input_v58_build_assertions\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-008\",\n      \"change_family\": \"GOVERNANCE\",\n      \"historical_subject\": \"STAGE_BOUND_PRIOR_ART_NOT_UPSTREAM_AUTHORITY\",\n      \"source_refs\": [\n        \"lf_eventos://20335\",\n        \"supabase://programacion.fn_agent_task_execution_bundle\",\n        \"supabase://programacion.fn_test_contract_generation_source\"\n      ]\n    }\n  ],\n  \"schema_version\": \"A12_ARMS_INPUT_V1\"\n}","input_origin":"A12 arms fixture (9dbc2185a3ba5f9f2b84e6380bdf86d610d0ce88701dbb9394ff98e8bb06fa4b)","input_sha256":"9dbc2185a3ba5f9f2b84e6380bdf86d610d0ce88701dbb9394ff98e8bb06fa4b","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"limits":{"checkpoint_transition":false,"db_write":false,"independent_assurance_admitted":false,"provider_attested":false,"real_execution_receipt":false,"transcript_is_provider_evidence":false},"output_contract":{"required_keys":["schema_version","request_ref","arms","comparison","no_ready_claim","arms_statement"],"schema":"A12_ARMS_OUTPUT_V1","validator":"analysis_qualification_a12q_c2_gpt_native_packet_v1.py::semantic_checks"},"owner_approval_doc":"docs/programming-agent/ANALYSIS_C2C3_GPT_NATIVE_APPROVED_EQUIVALENT_V1.md","packet_sha256":"250f2e050ccf0df31c5fc7efe47460fb7e28ef05122f23a531d087676b326a99","producer_mode":"GPT_NATIVE","profile_source":{"ref":"profiles/programming_analysis_lf/SKILL.md","sha256":"91a7b47c3d84f1d5aea48f3fd475134d9c56c718461d1b649c4a89d53980508f"},"prompt_for_gpt":"Este mensaje es independiente: ignora cualquier otro paquete o salida anterior de este chat. Eres el productor de la etapa A12 (comparación de dos brazos sobre los mismos casos) del perfil de análisis. Recibes 7 casos (cases), la lista de dominios fijos del brazo baseline (baseline_fixed_domains) y la descripción de cada brazo (arms) (abajo). NO se suministra el contenido de las fuentes: todo es hipótesis a partir del asunto. Produce AMBOS brazos para los MISMOS 7 casos. Baseline: por cada caso, TODOS los dominios fijos, sin importar la evidencia. Candidate: por cada caso, solo los frentes que una referencia del propio caso permita justificar. No declares READY, no ejecutes nada, no mides nada. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, arms, comparison, no_ready_claim, arms_statement. schema_version='A12_ARMS_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. arms: objeto con exactamente las claves baseline y candidate, cada una una lista con un registro por caso (7). Registro baseline, con exactamente las claves case_id, domains, evidence_refs, reinterpretation_required, verdict: case_id; verdict: BLOCKED|REQUIRES_DECISION|NEED_MORE_EVIDENCE; domains: lista con un elemento {domain, note} por CADA dominio fijo (note: texto de al menos 10 caracteres); evidence_refs: lista no vacía, sin repetidos, con source_refs del propio caso; reinterpretation_required: booleano. Registro candidate, con exactamente las claves case_id, evidence_refs, fronts, reinterpretation_required, verdict: case_id; verdict igual que arriba; fronts: lista no vacía de {front (texto corto), trigger_ref (una source_ref del propio caso), reason (texto de al menos 10 caracteres)}; evidence_refs y reinterpretation_required como arriba. comparison: objeto con exactamente las claves baseline_fixed_domains_per_case, baseline_total_domains, candidate_total_fronts, cases_compared (enteros): casos comparados, total de dominios del baseline sumando todos los casos, total de frentes del candidate sumando todos los casos, y número de dominios fijos por caso. No incluyas latencia, tokens, proveedor ni identificadores de ejecución. no_ready_claim=true. arms_statement: texto de al menos 40 caracteres que diga que ambos brazos fueron producidos, no medidos, y que no es una comparación de rendimiento.\n\nENTRADA (JSON):\n{\n  \"arms\": {\n    \"baseline\": \"Método de dominios fijos: aplica a cada caso la lista completa de dominios obligatorios, independientemente de la evidencia del caso (salida histórica tipo STORY_PACK).\",\n    \"candidate\": \"Método de frentes activados por evidencia: solo registra los frentes materiales que una referencia del propio caso permita justificar (salida tipo paquete de análisis).\"\n  },\n  \"baseline_fixed_domains\": [\n    \"ALCANCE\",\n    \"DATOS\",\n    \"PERMISOS\",\n    \"ESTADOS\",\n    \"ERRORES\",\n    \"EFECTOS_COLATERALES\"\n  ],\n  \"cases\": [\n    {\n      \"case_id\": \"A10-HIST-001\",\n      \"change_family\": \"FEATURE\",\n      \"historical_subject\": \"PROGRAMMING_AGENT_TARGET_STATE_DESIGN_BINDING_REFINEMENT_V1\",\n      \"source_refs\": [\n        \"lf_eventos://20397\",\n        \"github://cristhianlujan/claude-persona-lf-patch/pull/1800\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-002\",\n      \"change_family\": \"MIGRATION\",\n      \"historical_subject\": \"PASE-ATOM-F09-S02\",\n      \"source_refs\": [\n        \"lf_eventos://20356\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-003\",\n      \"change_family\": \"RUNTIME\",\n      \"historical_subject\": \"PASE-ATOM-F09-S03\",\n      \"source_refs\": [\n        \"lf_eventos://20357\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-004\",\n      \"change_family\": \"CONCURRENCY_IDEMPOTENCY\",\n      \"historical_subject\": \"PAULO-148\",\n      \"source_refs\": [\n        \"lf_eventos://20268\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-005\",\n      \"change_family\": \"MODEL_OR_INTELLIGENCE\",\n      \"historical_subject\": \"PROGRAMMING_AGENT_WAVE2_SELECTION_METHOD_CANDIDATE_FREEZE_R2\",\n      \"source_refs\": [\n        \"lf_eventos://20373\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-006\",\n      \"change_family\": \"BUG\",\n      \"historical_subject\": \"INPUT_GOVERNANCE_NUMERIC_SCREEN_IDENTITY\",\n      \"source_refs\": [\n        \"supabase://programacion.fn_input_v58_assertion_template\",\n        \"supabase://programacion.fn_input_v512_assertion_template\",\n        \"supabase://programacion.fn_input_v58_build_assertions\"\n      ]\n    },\n    {\n      \"case_id\": \"A10-HIST-008\",\n      \"change_family\": \"GOVERNANCE\",\n      \"historical_subject\": \"STAGE_BOUND_PRIOR_ART_NOT_UPSTREAM_AUTHORITY\",\n      \"source_refs\": [\n        \"lf_eventos://20335\",\n        \"supabase://programacion.fn_agent_task_execution_bundle\",\n        \"supabase://programacion.fn_test_contract_generation_source\"\n      ]\n    }\n  ],\n  \"schema_version\": \"A12_ARMS_INPUT_V1\"\n}","request_sha256":"bdc14baad8224114b640764f0217d85bc73652e59d70650bd2c70bc614296628","run_id":"A12Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A12","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A12Q/A12Q_C2","unit":"A12"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A12Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A12Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A12Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A12Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A12Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A12Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A12Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A12Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A12Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A12Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A12Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A12Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A12Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A12Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A12Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A12Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A12Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a12q_c2_prep$;
COMMIT;
